import functools

def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            main_part, pre = core.split('-', 1)
        else:
            main_part = core
        major, minor, patch = (int(x) for x in main_part.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def compare_pre(a, b):
        # a, b are lists of identifiers or None
        if a is None and b is None:
            return 0
        if a is None:
            return 1  # no prerelease > has prerelease
        if b is None:
            return -1
        for ai, bi in zip(a, b):
            a_num = ai.isdigit()
            b_num = bi.isdigit()
            if a_num and b_num:
                na, nb = int(ai), int(bi)
                if na != nb:
                    return -1 if na < nb else 1
            elif a_num and not b_num:
                return -1
            elif not a_num and b_num:
                return 1
            else:
                if ai != bi:
                    return -1 if ai < bi else 1
        if len(a) != len(b):
            return -1 if len(a) < len(b) else 1
        return 0

    def compare(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return compare_pre(p1[3], p2[3])

    return sorted(versions, key=functools.cmp_to_key(compare))

